-- 2026-11-12-wardogs-season3-price-level-updates.sql
-- Brief 369. Six Season 3 value changes from Bulkhead's Season 03 patch notes (Steam, Nov 11, 2026), https://store.steampowered.com/news/app/1867240/view/688648135317127221
-- NOT RUN by the executor. The operator runs each statement alone in the Supabase SQL editor, in order: BEFORE, the six UPDATEs, VERIFY.
-- Each statement is on ONE line. Plain single-quoted strings with doubled apostrophes, no dollar quotes, no semicolon inside any quoted string.
-- Each UPDATE sets one value, appends one dated line to verified_source (the Season 2 convention, URL included) and sets updated_at = now().
-- verified, tier and every other column are unchanged. C4 Detonator (id 40) is not touched.
-- Guard on every UPDATE: id, game_slug, the exact "from" value and md5 of the current verified_source. A re-run or a changed row updates 0 rows.
-- updated_at: weapon_stats has a BEFORE UPDATE trigger (HANDOFF 2026-08-03); wardogs_economy_items has none in its schema file. now() is set explicitly on both.

-- BEFORE: run this alone. Expect 6 rows: 5 Kodiak 6750, 17 AH-6M Miniguns 12000, 21 Havoc 28000, 39 C4 level 4, 51 Wolf-110 7800, AMR 50 level 35.
SELECT 'wardogs_economy_items' AS tbl, id::text AS id, name, category, cost AS price, cost_basis, unlock_track AS track, unlock_level AS level, unlock_fee, tier, verified, updated_at, char_length(verified_source) AS vs_chars, md5(verified_source) AS vs_md5, position(chr(13) in verified_source) AS vs_cr_pos, verified_source FROM wardogs_economy_items WHERE game_slug = 'wardogs' AND id IN (51, 5, 17, 21, 39) UNION ALL SELECT 'weapon_stats', id::text, name, category, credit_cost, NULL, unlock_class, unlock_class_level, unlock_fee, NULL, verified, updated_at, char_length(verified_source), md5(verified_source), position(chr(13) in verified_source), verified_source FROM weapon_stats WHERE game_slug = 'wardogs' AND id = 'd77615ea-9f15-4696-b997-7a91cfdbb53d' ORDER BY tbl, id;

-- UPDATE 1: Wolf-110 M2 Browning cost 7800 -> 6800. Run alone. Expect UPDATE 1.
UPDATE wardogs_economy_items SET cost = 6800, verified_source = verified_source || ' | Update 2026-11-12: vendor price for this row now from Bulkhead''s Season 03 patch notes (Steam, Nov 11, 2026), https://store.steampowered.com/news/app/1867240/view/688648135317127221, and it supersedes the Season 2 value named above.', updated_at = now() WHERE id = 51 AND game_slug = 'wardogs' AND cost = 7800 AND md5(verified_source) = '597b6180245192b8f504d220bf14e88f';

-- UPDATE 2: Kodiak M249 cost 6750 -> 6250. Run alone. Expect UPDATE 1.
UPDATE wardogs_economy_items SET cost = 6250, verified_source = verified_source || ' | Update 2026-11-12: vendor price for this row now from Bulkhead''s Season 03 patch notes (Steam, Nov 11, 2026), https://store.steampowered.com/news/app/1867240/view/688648135317127221, and it supersedes the Season 2 value named above.', updated_at = now() WHERE id = 5 AND game_slug = 'wardogs' AND cost = 6750 AND md5(verified_source) = '0fb6a2e60efc46a408092eb630a22819';

-- UPDATE 3: AH-6M Miniguns cost 12000 -> 10480. Run alone. Expect UPDATE 1.
UPDATE wardogs_economy_items SET cost = 10480, verified_source = verified_source || ' | Update 2026-11-12: vendor price for this row now from Bulkhead''s Season 03 patch notes (Steam, Nov 11, 2026), https://store.steampowered.com/news/app/1867240/view/688648135317127221, and it supersedes the Season 2 value named above.', updated_at = now() WHERE id = 17 AND game_slug = 'wardogs' AND cost = 12000 AND md5(verified_source) = 'a978f527b51a4ca8d09ac10e3c4e63a0';

-- UPDATE 4: Havoc cost 28000 -> 26000. Run alone. Expect UPDATE 1.
UPDATE wardogs_economy_items SET cost = 26000, verified_source = verified_source || ' | Update 2026-11-12: vendor price for this row now from Bulkhead''s Season 03 patch notes (Steam, Nov 11, 2026), https://store.steampowered.com/news/app/1867240/view/688648135317127221, and it supersedes the Season 2 value named above.', updated_at = now() WHERE id = 21 AND game_slug = 'wardogs' AND cost = 28000 AND md5(verified_source) = '6c064ef81e1e9671f8c811986bee75eb';

-- UPDATE 5: C4 unlock_level 4 -> 5. Run alone. Expect UPDATE 1.
UPDATE wardogs_economy_items SET unlock_level = 5, verified_source = verified_source || ' | Update 2026-11-12: unlock level for this row now from Bulkhead''s Season 03 patch notes (Steam, Nov 11, 2026), https://store.steampowered.com/news/app/1867240/view/688648135317127221, and it supersedes the Season 2 value named above.', updated_at = now() WHERE id = 39 AND game_slug = 'wardogs' AND unlock_level = 4 AND md5(verified_source) = '75d3f4d19b7f78b8c9ce27f2d6993fe7';

-- UPDATE 6: AMR 50 unlock_class_level 35 -> 41. Run alone. Expect UPDATE 1.
UPDATE weapon_stats SET unlock_class_level = 41, verified_source = verified_source || ' | Update 2026-11-12: class unlock level for this row now from Bulkhead''s Season 03 patch notes (Steam, Nov 11, 2026), https://store.steampowered.com/news/app/1867240/view/688648135317127221, and it supersedes the community-aggregated Season 1 value named above.', updated_at = now() WHERE id = 'd77615ea-9f15-4696-b997-7a91cfdbb53d' AND game_slug = 'wardogs' AND unlock_class_level = 35 AND md5(verified_source) = '7cb9e1df3858e99e95a0f7ee645a2296';

-- VERIFY: run this alone. Expect 6 rows with the new values: 5 Kodiak 6250, 17 AH-6M Miniguns 10480, 21 Havoc 26000, 39 C4 level 5, 51 Wolf-110 6800, AMR 50 level 41.
-- Expected vs_chars and vs_md5 after: Wolf-110 M2 Browning 366 5a731920bc8e18ab6d455289067b07da, Kodiak M249 504 0391dde3f93157f3c10a0008d7216845, AH-6M Miniguns 713 dce0f735d99a128eb1d5485637e9ff18, Havoc 698 8de1e0c6bce2928004b7d3cfa5c479f6, C4 530 20591ff0513f84ba057951162228e5df, AMR 50 904 beccbb833c1b3f75e9fb2f8693bdc833. vs_cr_pos 0 on all six.
SELECT 'wardogs_economy_items' AS tbl, id::text AS id, name, category, cost AS price, cost_basis, unlock_track AS track, unlock_level AS level, unlock_fee, tier, verified, updated_at, char_length(verified_source) AS vs_chars, md5(verified_source) AS vs_md5, position(chr(13) in verified_source) AS vs_cr_pos, verified_source FROM wardogs_economy_items WHERE game_slug = 'wardogs' AND id IN (51, 5, 17, 21, 39) UNION ALL SELECT 'weapon_stats', id::text, name, category, credit_cost, NULL, unlock_class, unlock_class_level, unlock_fee, NULL, verified, updated_at, char_length(verified_source), md5(verified_source), position(chr(13) in verified_source), verified_source FROM weapon_stats WHERE game_slug = 'wardogs' AND id = 'd77615ea-9f15-4696-b997-7a91cfdbb53d' ORDER BY tbl, id;

